    expect_equal(waic2, waic_pointwise)
  )
  brms_port("brmsfit-methods:1021", "divergence",
    paste0(
      "waic(), WAIC() and add_criterion('waic') are refused by ",
      "name on a maximum-likelihood fit: WAIC averages over ",
      "posterior draws"),
    expect_warning(compare_ic(waic1, waic2),
                   "Model comparisons are likely invalid")
  )
  brms_setup("brmsfit-methods:1023",
    waic4 <- SW(waic(fit4))
  )
  brms_port("brmsfit-methods:1024", "divergence",
    paste0(
      "waic(), WAIC() and add_criterion('waic') are refused by ",
      "name on a maximum-likelihood fit: WAIC averages over ",
      "posterior draws"),
    expect_true(is.numeric(waic4$estimates))
  )
})
